script:
(function () {
  'use strict';
  // Multi-property like-kind exchange: up to 3 relinquished and 4 replacement real properties treated
  // as one exchange (all U.S. real property is one exchange group under Treas. Reg. 1.1031(j)-1 since
  // only real property qualifies after 2017). Totals follow IRS Form 8824 Part III (2025 instructions):
  //   net = (sum relinquished values - sum old mortgages) - (sum replacement prices - sum new mortgages)
  //         - FMV of other (non-like-kind) property received; cash in = max(0, net), cash paid = max(0, -net).
  //   Line 15 = cash in + other property FMV + max(0, old mortgages - (new mortgages + cash paid)),
  //             reduced (not below 0) by exchange expenses (selling + purchase costs).
  //   Line 18 = sum adjusted bases + expenses not used on line 15 + max(0, new mortgages + cash paid - old mortgages).
  //   Line 19 = line 15 + replacement prices - line 18 (realized); line 23 = max(0, min(line 15, line 19));
  //   line 24 = line 19 - line 23 (deferred); line 25 = line 18 + line 23 - line 15 (basis of all
  //   like-kind property received). Other property received takes its FMV as basis.
  //   Line 25 is allocated among the replacement properties in proportion to their prices (FMV);
  //   each property's built-in deferred gain = price - allocated basis (these sum to line 24).
  //   Per relinquished property: realized gain = value - adjusted basis - share of all exchange costs
  //   (by value); these sum to line 19.
  //   Identification: 3-property rule, else 200% rule (replacement value <= 2 x relinquished value),
  //   else the 95% rule (Treas. Reg. 1.1031(k)-1(c)(4)).
  // Verified (Node, scratchpad lkrepo/tests/lk.test.js): one property each side reproduces the
  //   Form 8824 instructions' Taylor example (line 15 $40,000, 18 $170,000, 19 $120,000, 20 $40,000)
  //   and the live 1031 tool's defaults; defaults here ($500k/$200k/$150k + $300k/$180k, $1.1M of
  //   replacements with $400k of new debt, $52k costs) -> realized $368,000 all deferred, total basis
  //   $732,000 = $1,100,000 - $368,000, split $432,545 / $299,455. Blank rows are skipped; negative
  //   input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pctFmt = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 });
  var REL = 3, REP = 4;

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return 0;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function signed(v) { return v < 0 ? '−' + money.format(-v) : money.format(v); }
  function sum(list, key) { return list.reduce(function (s, x) { return s + x[key]; }, 0); }

  function exchange(rel, rep, sellCost, buyCost, other) {
    var sale = sum(rel, 'value'), basis = sum(rel, 'basis'), oldDebt = sum(rel, 'debt');
    var buy = sum(rep, 'price'), newDebt = sum(rep, 'debt');
    var expenses = sellCost + buyCost;
    var net = (sale - oldDebt) - (buy - newDebt) - other;
    var cashIn = Math.max(0, net), cashOut = Math.max(0, -net);
    var debtRelief = Math.max(0, oldDebt - (newDebt + cashOut));
    var bootGross = cashIn + other + debtRelief;
    var expOn15 = Math.min(expenses, bootGross);
    var l15 = bootGross - expOn15;
    var l18 = basis + (expenses - expOn15) + Math.max(0, newDebt + cashOut - oldDebt);
    var l19 = l15 + buy - l18;
    var l23 = Math.max(0, Math.min(l15, l19));
    var l24 = l19 - l23;
    var l25 = l18 + l23 - l15;
    var relRows = rel.map(function (p) {
      var cost = sale > 0 ? expenses * p.value / sale : 0;
      return { n: p.n, value: p.value, basis: p.basis, cost: cost, gain: p.value - p.basis - cost };
    });
    var repRows = rep.map(function (p) {
      var share = buy > 0 ? p.price / buy : 0, b = l25 * share;
      return { n: p.n, price: p.price, debt: p.debt, share: share, basis: b, deferred: p.price - b, equity: p.price - p.debt };
    });
    return { sale: sale, basis: basis, oldDebt: oldDebt, buy: buy, newDebt: newDebt, expenses: expenses, net: net,
      cashIn: cashIn, cashOut: cashOut, debtRelief: debtRelief, expOn15: expOn15, l15: l15, l18: l18, l19: l19,
      l23: l23, l24: l24, l25: l25, relRows: relRows, repRows: repRows };
  }

  function identification(count, repValue, relValue) {
    if (count <= 3) return { rule: 'Three-property rule', ok: true, text: 'Up to three replacement properties can be identified regardless of value.' };
    if (repValue <= 2 * relValue) return { rule: '200% rule', ok: true, text: 'More than three properties, but their total value (' + money.format(repValue) + ') is no more than 200% of the property you sold (' + money.format(2 * relValue) + ' limit).' };
    return { rule: '95% rule only', ok: false, text: 'More than three properties worth over 200% of what you sold. The identification is valid only if you acquire at least 95% of the total value you identified.' };
  }

  var IDS = ['lkmDeferred', 'lkmRecognized', 'lkmRealized', 'lkmTotalBasis', 'lkmNote', 'lkmRelTotal', 'lkmRepTotal', 'lkmCash',
    'lkmCashBoot', 'lkmDebtBoot', 'lkmOtherBoot', 'lkmExpBoot', 'lkmBoot', 'lkmIdCount', 'lkmIdRule', 'lkmIdText'];

  function clear() {
    IDS.forEach(function (id) { setText(id, '–'); });
    el('lkmRelRows').innerHTML = '';
    el('lkmRepRows').innerHTML = '';
  }

  function update() {
    var rel = [], rep = [], bad = false, i, v;
    for (i = 1; i <= REL; i++) {
      var p = { n: i, value: read('lkmRv' + i), basis: read('lkmRb' + i), debt: read('lkmRd' + i) };
      if ([p.value, p.basis, p.debt].some(function (x) { return isNaN(x) || x < 0 || x > 1e12; })) bad = true;
      else if (p.value > 0) rel.push(p);
      else if (p.basis > 0 || p.debt > 0) bad = bad || 'value';
    }
    for (i = 1; i <= REP; i++) {
      var q = { n: i, price: read('lkmNv' + i), debt: read('lkmNd' + i) };
      if ([q.price, q.debt].some(function (x) { return isNaN(x) || x < 0 || x > 1e12; })) bad = true;
      else if (q.price > 0) rep.push(q);
      else if (q.debt > 0) bad = bad || 'price';
    }
    var sellCost = read('lkmSellCost'), buyCost = read('lkmBuyCost'), other = read('lkmOther');
    var err = el('lkmError'), msg = '';
    if (bad === true) msg = 'Amounts must be numbers of $0 or more.';
    else if ([sellCost, buyCost, other].some(function (x) { return isNaN(x) || x < 0 || x > 1e12; })) msg = 'Costs and other property received must be $0 or more.';
    else if (bad === 'value') msg = 'Enter a sale price for every property you are giving up that has a basis or mortgage.';
    else if (bad === 'price') msg = 'Enter a purchase price for every replacement property that has a mortgage.';
    else if (!rel.length) msg = 'Enter the sale price of at least one property you are giving up.';
    else if (!rep.length) msg = 'Enter the purchase price of at least one replacement property.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { clear(); return; }

    var r = exchange(rel, rep, sellCost, buyCost, other);
    setText('lkmDeferred', signed(r.l24));
    setText('lkmRecognized', money.format(r.l23));
    setText('lkmRealized', signed(r.l19));
    setText('lkmTotalBasis', money.format(r.l25));
    setText('lkmRelTotal', money.format(r.sale) + ' (' + rel.length + (rel.length === 1 ? ' property)' : ' properties)'));
    setText('lkmRepTotal', money.format(r.buy) + ' (' + rep.length + (rep.length === 1 ? ' property)' : ' properties)'));
    var left = r.net - r.expenses;
    setText('lkmCashLabel', left >= 0 ? 'Cash left over for you after costs' : 'Extra cash you add, including costs');
    setText('lkmCash', money.format(Math.abs(left)));
    setText('lkmCashBoot', money.format(r.cashIn));
    setText('lkmDebtBoot', money.format(r.debtRelief));
    setText('lkmOtherBoot', money.format(other));
    setText('lkmExpBoot', r.expOn15 > 0 ? '−' + money.format(r.expOn15) : money.format(0));
    setText('lkmBoot', money.format(r.l15));

    var id = identification(rep.length, r.buy, r.sale);
    setText('lkmIdCount', String(rep.length));
    setText('lkmIdRule', id.rule);
    setText('lkmIdText', id.text);

    var note;
    if (r.l19 <= 0) note = 'Taken together, the exchange realizes a loss. It cannot be deducted; it is carried into the replacement properties through their basis.';
    else if (r.l23 <= 0) note = 'The whole ' + money.format(r.l19) + ' gain is deferred. The replacement properties cost at least as much as you sold for, and the new debt and cash you put in cover the mortgages paid off.';
    else note = money.format(r.l23) + ' of the gain is taxed now because you receive ' + money.format(r.l15) + ' of boot (cash, debt relief or other property, after costs). The other ' + signed(r.l24) + ' is deferred.';
    if (other > 0) note += ' The other property you receive takes its fair market value, ' + money.format(other) + ', as its basis.';
    setText('lkmNote', note);

    el('lkmRelRows').innerHTML = r.relRows.map(function (x) {
      return '<tr><td>Property ' + x.n + '</td><td>' + money.format(x.value) + '</td><td>' + money.format(x.basis) + '</td><td>' +
        money.format(x.cost) + '</td><td>' + signed(x.gain) + '</td></tr>';
    }).join('') + '<tr><th scope="row">Total</th><td>' + money.format(r.sale) + '</td><td>' + money.format(r.basis) + '</td><td>' +
      money.format(r.expenses) + '</td><td>' + signed(r.l19) + '</td></tr>';
    el('lkmRepRows').innerHTML = r.repRows.map(function (x) {
      return '<tr><td>Property ' + String.fromCharCode(64 + x.n) + '</td><td>' + money.format(x.price) + '</td><td>' + pctFmt.format(x.share) + '</td><td>' +
        signed(x.basis) + '</td><td>' + signed(x.deferred) + '</td><td>' + signed(x.equity) + '</td></tr>';
    }).join('') + '<tr><th scope="row">Total</th><td>' + money.format(r.buy) + '</td><td>100%</td><td>' + signed(r.l25) + '</td><td>' +
      signed(r.buy - r.l25) + '</td><td>' + signed(r.buy - r.newDebt) + '</td></tr>';
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('lkmForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
